const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const files={"src/app/about/page.tsx": "import Image from 'next/image';\nimport Link from 'next/link';\nimport { AppHeader } from '@/components/layout/AppHeader';\n\nexport const metadata = { title: 'About | A-Factor STEM Studio' };\n\nconst portfolio = 'https://mrdof-portfolio.vercel.app/';\n\nexport default function AboutPage() {\n  return (\n    <>\n      <AppHeader />\n      <main className=\"mx-auto max-w-4xl space-y-5 px-4 py-5 text-gray-900 sm:px-6 sm:py-8\">\n        <section className=\"rounded-2xl border border-indigo-100 bg-indigo-50 p-4 sm:p-6\">\n          <p className=\"text-xs font-semibold uppercase tracking-wide text-indigo-700\">A-Factor STEM Studio</p>\n          <h1 className=\"mt-1 text-2xl font-bold tracking-tight sm:text-4xl\">Learn STEM by doing</h1>\n          <p className=\"mt-2 max-w-2xl text-sm leading-relaxed text-gray-700 sm:text-base\">\n            A-Factor brings interactive STEM learning to students and teachers, with African classrooms in mind.\n            Change a variable, observe what happens and connect the result to the science or mathematics behind it.\n          </p>\n          <div className=\"mt-4 flex flex-wrap gap-2\">\n            <Link href=\"/stem\" className=\"inline-flex min-h-11 items-center rounded-lg bg-indigo-700 px-4 text-sm font-semibold text-white hover:bg-indigo-800\">\n              Explore all simulations\n            </Link>\n            <Link href=\"/tutor\" className=\"inline-flex min-h-11 items-center rounded-lg border border-indigo-200 bg-white px-4 text-sm font-semibold text-indigo-800\">\n              Open STEM Tutor\n            </Link>\n          </div>\n        </section>\n\n        <section aria-labelledby=\"learning-at-afactor\">\n          <h2 id=\"learning-at-afactor\" className=\"text-lg font-semibold\">What you can do</h2>\n          <ul className=\"mt-2 grid gap-2 sm:grid-cols-2\">\n            <li className=\"rounded-xl border border-gray-200 bg-white p-3 text-sm leading-relaxed text-gray-700\">\n              <strong className=\"block text-gray-900\">Explore across subjects</strong>\n              Investigate atoms, cells, materials, Earth systems and mathematical relationships.\n              Use circuit and materials simulations to connect scientific ideas to technology and engineering.\n            </li>\n            <li className=\"rounded-xl border border-gray-200 bg-white p-3 text-sm leading-relaxed text-gray-700\">\n              <strong className=\"block text-gray-900\">Teach and practise</strong>\n              Run classroom demonstrations, compare predictions with results and use worked examples and exercises where available.\n            </li>\n          </ul>\n        </section>\n\n        <details className=\"rounded-xl border border-gray-200 bg-white p-3\">\n          <summary className=\"cursor-pointer text-sm font-semibold\">Curriculum and language support</summary>\n          <p className=\"mt-2 text-sm leading-relaxed text-gray-600\">\n            Explore activities tagged for WAEC, NECO, IGCSE, JUPEB and SAT on the subject pages.\n            The topic explorer offers English, Yorùbá, Hausa and Igbo options.\n          </p>\n        </details>\n\n        <section aria-labelledby=\"founder-heading\" className=\"flex items-start gap-3 rounded-xl border border-gray-200 bg-white p-3 sm:gap-4 sm:p-4\">\n          <Image src=\"/iamdof-avatar.jpg\" alt=\"Fatai Olalekan Dawodu\" width={64} height={64}\n            className=\"h-14 w-14 shrink-0 rounded-full object-cover sm:h-16 sm:w-16\" />\n          <div className=\"min-w-0\">\n            <h2 id=\"founder-heading\" className=\"text-base font-semibold\">IamDOF 🕶</h2>\n            <p className=\"text-sm text-gray-700\">Fatai Olalekan Dawodu · Founder and educator</p>\n            <p className=\"mt-1 text-sm leading-relaxed text-gray-600\">\n              I build A-Factor to make STEM easier to teach, explore and practise.\n            </p>\n            <a href={portfolio} className=\"mt-1 inline-flex min-h-10 items-center text-sm font-semibold text-indigo-700 hover:underline\">\n              View my portfolio →\n            </a>\n          </div>\n        </section>\n      </main>\n      <footer className=\"border-t border-gray-200 bg-white\">\n        <div className=\"mx-auto max-w-4xl space-y-2 px-4 py-4 sm:px-6\">\n          <div className=\"flex flex-wrap items-center gap-x-2 gap-y-1 text-sm text-gray-600\">\n            <Image src=\"/icon.png\" alt=\"\" width={20} height={20} className=\"rounded\" />\n            <strong className=\"text-gray-900\">A-Factor STEM Studio</strong>\n            <span className=\"text-xs\">© {new Date().getFullYear()} A-Factor EdTech Solutions</span>\n          </div>\n          <nav aria-label=\"About footer\" className=\"flex flex-wrap gap-x-4 text-sm text-gray-700\">\n            <Link href=\"/\" className=\"inline-flex min-h-10 items-center hover:underline\">Home</Link>\n            <Link href=\"/stem\" className=\"inline-flex min-h-10 items-center hover:underline\">Simulations</Link>\n            <Link href=\"/about\" aria-current=\"page\" className=\"inline-flex min-h-10 items-center hover:underline\">About</Link>\n            <a href={portfolio} target=\"_blank\" rel=\"noopener noreferrer\" className=\"inline-flex min-h-10 items-center hover:underline\">Portfolio ↗</a>\n            <Link href=\"/privacy/analytics\" className=\"inline-flex min-h-10 items-center hover:underline\">Usage privacy</Link>\n            <Link href=\"/minitab/admin/login\" className=\"inline-flex min-h-10 items-center hover:underline\">Instructor Login</Link>\n          </nav>\n        </div>\n      </footer>\n    </>\n  );\n}\n"},expected={"src/app/about/page.tsx": "375b5a9ce766b3530f1764be5e1c2d14e4ff0d3ec643e2452ee86781c218a01c"};
const root=process.cwd(),normalize=s=>Buffer.isBuffer(s)?s:s.replace(/\r\n/g,'\n'),hash=s=>crypto.createHash('sha256').update(normalize(s)).digest('hex');
function stop(message){console.error('Stopped: '+message+' No source files changed.');process.exit(1);}
if(!fs.existsSync('package.json')||!fs.existsSync('src/app/simulations/atomic-models/page.tsx'))stop('Run this patch from your A-Factor project root.');
for(const file of [...Object.keys(files),'.stem-tutor-backups']){let item=root;for(const part of file.split('/')){item=path.join(item,part);try{if(fs.lstatSync(item).isSymbolicLink())stop('Symbolic link at '+file);}catch(e){if(e.code!=='ENOENT')throw e;}}}
if (!fs.existsSync('src/app/stem/page.tsx')) stop('Install the STEM catalog first.');
const changed=[],conflicts=[];
for(const [file,content]of Object.entries(files)){const current=fs.existsSync(file)?fs.readFileSync(file,Buffer.isBuffer(content)?undefined:'utf8'):null;if(current!==null&&(Buffer.isBuffer(content)?content.equals(current):normalize(current)===normalize(content)))continue;if(current===null?expected[file]!==null:expected[file]===null||hash(current)!==expected[file])conflicts.push(file);else changed.push(file);}
if(conflicts.length)stop('These files differ from the source version used to prepare this STEM update. Preserve your edits and request a refreshed patch:\n'+conflicts.join('\n'));
if(!changed.length){console.log('The About update are already installed.');process.exit(0);}
fs.mkdirSync('.stem-tutor-backups',{recursive:true});const backup=fs.mkdtempSync('.stem-tutor-backups/about-'),originals=new Map();
for(const file of changed){const content=fs.existsSync(file)?fs.readFileSync(file):null;originals.set(file,content);if(content!==null){const copy=path.join(backup,file);fs.mkdirSync(path.dirname(copy),{recursive:true});fs.writeFileSync(copy,content);}}
fs.writeFileSync(path.join(backup,'manifest.json'),JSON.stringify(changed.map(file=>({file,existed:originals.get(file)!==null})),null,2));
try{for(const file of changed){fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,files[file],'utf8');}}catch(error){for(const [file,content]of originals){if(content===null){if(fs.existsSync(file))fs.unlinkSync(file);}else fs.writeFileSync(file,content);}console.error('Write failed; originals restored: '+error.message);process.exit(1);}
console.log('Restored the About footer.');
console.log('Backup: '+backup);console.log('No new packages required.');console.log('Check: npm run build');
AF_ABOUT_FOOTER_PATCH
